function e(e){return e(`Это карточка-портрет схемы — какая она у тебя. Заполни один раз, дополняй при желании — она останется в «Моих заметках», а разбор конкретного случая, когда схема включилась, — в «Дневнике схем».`,`Это карточка-портрет схемы — какая она у вас. Заполните один раз, дополняйте при желании — она останется в «Моих заметках», а разбор конкретного случая, когда схема включилась, — в «Дневнике схем».`)}function t(e){return e(`Это запись про один конкретный момент — что случилось и какие твои схемы включились. Записей будет много, а общий портрет схемы — в карточке «Знакомство со схемой».`,`Это запись про один конкретный момент — что случилось и какие ваши схемы включились. Записей будет много, а общий портрет схемы — в карточке «Знакомство со схемой».`)}export{e as n,t};